(()=>{'use strict';const api=window.omniAddon;if(!api||!api.top)return;const core=OmniSpeedCore,session=new core.Session();let enabled=false,root,select,value,message,observer,timer,videos=[],scans=0;const node=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e};function show(text){message.textContent=text}function selected(){return videos[Number(select.value)]}function refresh(){timer=null;if(!enabled)return;scans++;const current=selected();videos=[...document.querySelectorAll('video')].filter(v=>!v.closest('[data-omni-addon]')).slice(0,100);select.replaceChildren();select.disabled=!videos.length;videos.forEach((v,i)=>{const o=new Option(String(v.getAttribute('aria-label')||v.title||'Video '+(i+1)).slice(0,80),String(i));select.add(o)});select.value=String(Math.max(0,videos.indexOf(current)));root.querySelectorAll('[data-change]').forEach(b=>b.disabled=!videos.length);value.textContent=videos.length?selected().playbackRate.toFixed(2)+'×':'—';show(videos.length?'Choose a video, then adjust its speed.':'No HTML video is available on this page.')}function change(direction){const video=selected();if(!video)return;try{const next=direction===0?1:core.step(video.playbackRate,direction,Number(api.settings.get('step')||.25));session.set(video,next);value.textContent=next.toFixed(2)+'×';show('Playback speed changed.')}catch(_){show('This video did not accept the speed change.')}}function start(){if(enabled)return;enabled=true;root=node('aside');root.id='omni-video-speed-panel';root.dataset.omniAddon=api.id;root.className='omni-addon-panel';root.setAttribute('aria-label','Video speed');root.append(node('h2','Video speed'));const label=node('label','Video ');select=node('select');label.append(select);root.append(label);value=node('output');value.setAttribute('aria-live','polite');root.append(value);for(const[text,n]of[['Slower',-1],['Normal speed',0],['Faster',1]]){const b=node('button',text);b.type='button';b.dataset.change=String(n);b.onclick=()=>change(n);root.append(b)}message=node('p');message.setAttribute('role','status');root.append(message);select.onchange=()=>{value.textContent=selected().playbackRate.toFixed(2)+'×'};root.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Escape'].includes(e.key))return;e.stopPropagation();if(e.key==='Escape'){e.preventDefault();root.querySelector('select').focus();return}if(e.target===select&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();select.selectedIndex=Math.max(0,Math.min(videos.length-1,select.selectedIndex+(e.key==='ArrowRight'?1:-1)));select.dispatchEvent(new Event('change'));return}e.preventDefault();const controls=[...root.querySelectorAll('button,select')].filter(x=>!x.disabled),i=controls.indexOf(document.activeElement);controls[Math.max(0,Math.min(controls.length-1,i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)))]?.focus()});document.body.append(root);OmniAddonControls.attach(root);refresh();observer=new MutationObserver(records=>{if(records.every(r=>root.contains(r.target)||[...r.addedNodes,...r.removedNodes].every(n=>n===root||root.contains(n))))return;if(!timer)timer=setTimeout(refresh,250)});observer.observe(document.body,{childList:true,subtree:true})}function stop(){enabled=false;clearTimeout(timer);timer=null;observer?.disconnect();session.restore();if(root?.contains(document.activeElement))root.omniRestoreFocus?.();root?.remove();videos=[]}api.onEnable(start);api.onDisable(stop);api.onSettings(()=>{if(enabled)show('Step size updated. Use Slower or Faster to apply it.')});window.OmniSpeedDiagnostics=()=>({enabled,tracked:videos.length,scans,retained:session.records.size});if(api.active)start()})();
